/**
 * `agent/storage.ts` and `agent/artifacts.ts`: host services the agent
 * configures. `agent/otel.ts` is rejected. OpenTelemetry is `OTEL_*`
 * variables.
 */
import { join } from "node:path";
import { defineArtifacts } from "../../artifacts.js";
import { artifactBuiltinTool, TAG_ARTIFACT_TOOL_NAME } from "../builtin-tools/index.js";
import { displayPath } from "./context.js";
import { findModuleFile } from "./fs.js";
import { importDefault } from "./modules.js";
export async function loadStorage(ctx, agentDir, architecture) {
    const path = await findModuleFile(agentDir, "storage");
    if (path === undefined) {
        return undefined;
    }
    if (architecture === "v2") {
        // Storage is a hosting-mode decision on v2, made by
        // framework-storage-selection.ts: the state root when self-hosted,
        // Cursor-managed storage on Cursor hosting. Fail early (error
        // diagnostics refuse serve and deploy) rather than silently running
        // with storage the author believes they configured. Not imported.
        ctx.diagnostics.push({
            severity: "error",
            path: displayPath(ctx, path),
            message: 'defineStorage is not supported on architecture "v2": the platform selects storage (the local state root when self-hosted; Cursor-managed storage on Cursor hosting). Delete the file.',
        });
        return undefined;
    }
    // v1 keeps loading the authored sink, with notice: defineStorage is going
    // away with the v1 control plane.
    ctx.diagnostics.push({
        severity: "warning",
        path: displayPath(ctx, path),
        message: 'defineStorage is deprecated and going away: architecture "v2" selects storage automatically (the local state root when self-hosted; Cursor-managed storage on Cursor hosting). Still honored on v1.',
    });
    const definition = await importDefault(ctx, path, "storage");
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the loader already checked this definition brand; importDefault returns unknown
    return definition;
}
const LEGACY_OTEL_MESSAGE = "bot/otel.ts and agent/otel.ts are removed. Delete this file. See https://cursor.com/docs/bdk/guides/opentelemetry#migrating-from-serve-otel.";
/** Fail discovery when the retired `otel.ts` module is still present. */
export async function rejectLegacyOtelModule(ctx, agentDir) {
    const path = await findModuleFile(agentDir, "otel");
    if (path === undefined) {
        return;
    }
    ctx.diagnostics.push({
        severity: "error",
        path: displayPath(ctx, path),
        message: LEGACY_OTEL_MESSAGE,
    });
}
export async function loadArtifacts(ctx, agentDir) {
    const path = await findModuleFile(agentDir, "artifacts");
    if (path === undefined) {
        return undefined;
    }
    const imported = await importDefault(ctx, path, "artifacts");
    if (imported === undefined) {
        return undefined;
    }
    // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the loader already checked this definition brand; importDefault returns unknown
    const definition = imported;
    if (definition.agentTool === true && Object.keys(definition.kinds ?? {}).length === 0) {
        ctx.diagnostics.push({
            severity: "error",
            path: displayPath(ctx, path),
            message: "artifacts.agentTool requires kinds: the tag_artifact tool needs at least one declared kind; its descriptions are the tool prompt.",
        });
    }
    return definition;
}
/**
 * `defineResult` / `agent/result.ts` is gone. A leftover file is an
 * authoring error so discovery fails closed instead of silently ignoring
 * host actuation that no longer runs.
 */
export async function rejectLegacyResult(ctx, agentDir) {
    const path = await findModuleFile(agentDir, "result");
    if (path === undefined) {
        return;
    }
    ctx.diagnostics.push({
        severity: "error",
        path: displayPath(ctx, path),
        message: "agent/result.ts is no longer supported; defineResult has been removed. Record structured output with an authored tool and actuate from a turn.completed hook.",
    });
}
/** Merge namespaced extension kinds onto the agent's artifacts registry. */
export function mergeArtifacts(agent, extra) {
    if (extra === undefined) {
        return agent;
    }
    if (agent === undefined) {
        return extra;
    }
    return defineArtifacts({
        kinds: { ...agent.kinds, ...extra.kinds },
        agentTool: agent.agentTool === true || extra.agentTool === true,
        max: agent.max ?? extra.max,
    });
}
/**
 * Materialize the `tag_artifact` built-in when `defineArtifacts` set
 * `agentTool: true`. Appended after `loadAgent` because the tool is
 * generated from the artifacts kinds registry, not `AgentConfig.builtinTools`.
 */
export async function appendArtifactTool(ctx, agentDir, agent, artifacts) {
    const tool = artifactBuiltinTool(artifacts);
    if (tool === undefined) {
        return;
    }
    const artifactsPath = displayPath(ctx, (await findModuleFile(agentDir, "artifacts")) ?? join(agentDir, "artifacts.ts"));
    if (agent.tools.some((t) => t.name === TAG_ARTIFACT_TOOL_NAME)) {
        ctx.diagnostics.push({
            severity: "warning",
            path: artifactsPath,
            message: `Authored tool "${TAG_ARTIFACT_TOOL_NAME}" shadows the built-in tool of the same name; the authored tool wins.`,
        });
        return;
    }
    agent.tools.push(tool);
}
